def f(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    # separators: full rows/cols of a single non-bg color forming lines
    second=[c for c,_ in cnt.most_common()[1:]][0]
    third=[c for c,_ in cnt.most_common()[2:]][0] if len(cnt)>2 else None
    seps=set(); 
    for r in range(H):
        if all(g[r][c]==second for c in range(W)): seps.add(('row',r))
    for c in range(W):
        if all(g[r][c]==second for r in range(H)): seps.add(('col',c))
    out=[row[:] for row in g]
    seeds=[(r,c) for r in range(H) for c in range(W) if g[r][c]==third]
    def paint(r,c,color):
        if 0<=r<H and 0<=c<W: out[r][c]=color
    for (sr,sc) in seeds:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            r,c=sr+dr,sc+dc; stop=False
            while 0<=r<H and 0<=c<W:
                v=g[r][c]
                if v==bg:
                    paint(r,c,third); r+=dr; c+=dc; continue
                elif v==second:
                    paint(r,c,third)   # crossing painted
                    if dr!=0: paint(r-1,c,second); paint(r+1,c,second)
                    else:      paint(r,c-1,second); paint(r,c+1,second)
                    stop=True
                break
            if not stop:
                # ray reached edge without hitting structure: does it leave anything? assume no.
                pass
    return out

