    def paint(r,c,v):
        if 0<=r<H and 0<=c<W: out[r][c]=v
    for (sr,sc) in seeds:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            r,c=sr+dr,sc+dc
