from collections import Counter
def solve(g):
    g=[list(map(int,r)) for r in g]; h,w=len(g),len(g[0])
    cnt={}
    for r in g:
        for c in r: cnt[c]=cnt.get(c,0)+1
    # line color: color owning full-height columns
    lines=set(); L=None
    for c,n in sorted(cnt.items(), key=lambda kv:-kv[1]):
        if any(all(g[r][j]==c for r in range(h)) for j in range(w)):
            lines={j for j in range(w) if all(g[r][j]==c for r in range(h))}
            L=c; break
    bg=cnt.most_common(1)[0][0]
    out=[r[:] for r in g]
    def block(lj):
        for rr in (r-1,r+1):
            if 0<=rr<h:
                for cc in (lj-1,lj,lj+1):
                    if 0<=cc<w: out[rr][cc]=L
    def center(lj):
        out[r][lj]=mv
    def ray(cc, sgn):
        # walk from cc in direction sgn, stop at line col or block cell
        while True:
            cc+=sgn
            if not (0<=cc<w): return
            if cc in lines: return
            if out[r][cc]!=bg: return
            out[r][cc]=mv
    for r in range(h):
        for c in range(w):
            mv=g[r][c]
