            for lj in lines:
                lo,hi=sorted((c,lj))
                if lo==hi: continue
                if lo<c: ray(lo+1,-1)
                elif hi>c: ray(hi-1,1)
                reached.add(lj)
            for lj in reached:
                block(lj); center(lj)
    return out
