def solve(g):
    g=[list(map(int,r)) for r in g]; h,w=len(g),len(g[0])
    cnt={}
    for r in g:
        for c in r: cnt[c]=cnt.get(c,0)+1
    bg=max(cnt,key=cnt.get)
    out=[r[:] for r in g]
    def mark(r,c,v):
        if 0<=r<h and 0<=c<w: out[r][c]=v
    lines=[]; L=None
    for j in range(w):
        col=g[0][j]
        if col!=bg and all(g[r][j]==col for r in range(h)):
            lines.append(j); L=col
    for r in range(h):
        for c in range(w):
            mv=g[r][c]
            if mv==bg or mv==L or c in lines: continue
            reached=[]
            for lj in sorted(lines):
                if lj>c: reached.append(lj); break
            for lj in reversed(sorted(lines)):
                if lj<c: reached.append(lj); break
            for lj in reached:
                for rr in (r-1,r,r+1):
                    for cc in (lj-1,lj,lj+1):
                        mark(rr,cc,L)
                mark(r,lj,mv)
                if lj<c:
                    for cc in range(lj+1,c):
                        if out[r][cc]==bg: mark(r,cc,mv)
                else:
                    for cc in range(c+1,lj):
                        if out[r][cc]==bg: mark(r,cc,mv)
    return out
